DO $test$ DECLARE t jsonb;passed integer:=0;denied boolean;ok boolean;BEGIN
FOR t IN SELECT value FROM jsonb_array_elements($cases$[{"name":"Administrateur scoped","role":"Administrateur","global":false,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Administrateur global","role":"Administrateur","global":true,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Coordonnateur scoped","role":"Coordonnateur","global":false,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Coordonnateur global","role":"Coordonnateur","global":true,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Client scoped","role":"Client","global":false,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Client global","role":"Client","global":true,"deny":true,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Client-Admin scoped","role":"Client-Admin","global":false,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Client-Admin global","role":"Client-Admin","global":true,"deny":true,"setup":"","sql":"select (public.portal_dashboard_summary()->>'version')::int=1"},{"name":"Denied {\"anon\":true}","role":"Administrateur","global":true,"deny":true,"setup":"","anon":true,"sql":"select public.portal_dashboard_summary() is not null"},{"name":"Denied {\"anonDb\":true}","role":"Administrateur","global":true,"deny":true,"setup":"","anonDb":true,"sql":"select public.portal_dashboard_summary() is not null"},{"name":"Denied {\"missing\":true}","role":"Administrateur","global":true,"deny":true,"setup":"","missing":true,"sql":"select public.portal_dashboard_summary() is not null"},{"name":"Client B zero infrastructure","role":"Client","global":false,"foreign":true,"deny":false,"setup":"","sql":"select (public.portal_dashboard_summary()->'sections'->'supports'->>'total')::int=1"},{"name":"Role visibility suppresses counters","role":"Administrateur","global":true,"deny":false,"setup":"update public.role_ui_permissions set visible_tables=array['Photos'] where role='Administrateur';","sql":"select public.portal_dashboard_summary()->'kpis' ? 'photos' and not(public.portal_dashboard_summary()->'kpis' ? 'infrastructures_active')"},{"role":"Client","global":false,"deny":false,"setup":"insert into public.infrastructures(id,support_id,client_id,actif) values(-91803,'SEC-EXT-A2',-91801,'Non');","name":"Server total exceeds one row","sql":"select (public.portal_dashboard_summary()->'sections'->'supports'->>'total')::int=2 and (public.portal_dashboard_summary()->'kpis'->>'infrastructures_active')::int=1"},{"role":"Client","global":false,"deny":true,"setup":"update public.utilisateurs set role=null where id=-91899;","name":"Null role denied","sql":"select public.portal_dashboard_summary() is not null"},{"role":"Client","global":false,"deny":false,"setup":"","name":"Anon execute revoked","sql":"select not has_function_privilege('anon','public.portal_dashboard_summary()','EXECUTE') and not has_function_privilege('anon','public.dashboard_key(text)','EXECUTE') and not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname='portal_dashboard_summary' and pronargs<>0)"},{"role":"Client","global":false,"deny":false,"setup":"","name":"Client B gets no A photos or EDT","foreign":true,"sql":"select (public.portal_dashboard_summary()->'sections'->'photos'->>'total')::int=0 and (public.portal_dashboard_summary()->'sections'->'edt'->>'total')::int=0"},{"role":"Client","global":false,"deny":false,"setup":"update public.role_ui_permissions set visible_tables=array['Photos'] where role='Client';","name":"Client role visibility suppresses infrastructure","sql":"select public.portal_dashboard_summary()->'sections' ? 'photos' and not(public.portal_dashboard_summary()->'sections' ? 'supports')"}]$cases$::jsonb) LOOP BEGIN
perform set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000091898',true);

update public.suivi_des_edt set statut='Complété',requester_contact_id=-91802,client_visible=true where id=-91801;
IF coalesce((t->>'missing')::boolean,false) THEN DELETE FROM public.utilisateurs WHERE id=-91899;END IF;
UPDATE public.role_ui_permissions SET visible_tables=ARRAY['*'] WHERE role=t->>'role';INSERT INTO public.role_ui_permissions(role,visible_tables,visible_columns) SELECT t->>'role',ARRAY['*'],'{}' WHERE NOT EXISTS(SELECT 1 FROM public.role_ui_permissions WHERE role=t->>'role');
IF t->>'setup'<>'' THEN BEGIN EXECUTE t->>'setup';EXCEPTION WHEN raise_exception THEN IF t->>'name'='mismatched campaign owner refused' AND SQLERRM='CROSS_CLIENT_ASSIGNMENT_DENIED' THEN RAISE EXCEPTION 'rollback fixture' USING ERRCODE='Z0001';ELSE RAISE;END IF;END;END IF;
perform set_config('request.jwt.claim.sub',case when coalesce((t->>'anon')::boolean,false) then '' else '91000000-0000-4000-8000-000000091899' end,true);
perform set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE authenticated;denied:=false;ok:=false;
IF coalesce((t->>'anonDb')::boolean,false) THEN SET LOCAL ROLE anon;END IF;
BEGIN EXECUTE t->>'sql' INTO ok;EXCEPTION WHEN insufficient_privilege THEN denied:=true;WHEN serialization_failure THEN IF coalesce((t->>'conflict')::boolean,false) THEN denied:=true;ELSE RAISE;END IF;END;RESET ROLE;
IF (t->>'deny')::boolean OR coalesce((t->>'conflict')::boolean,false) THEN IF NOT denied THEN RAISE EXCEPTION 'scope bypass %',t->>'name';END IF;
ELSIF denied OR ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'legitimate behavior failed %, denied %, ok %',t->>'name',denied,ok;END IF;
RAISE EXCEPTION 'rollback fixture' USING ERRCODE='Z0001';EXCEPTION WHEN SQLSTATE 'Z0001' THEN passed:=passed+1;END;END LOOP;
IF passed<>18 THEN RAISE EXCEPTION 'missing cases %',passed;END IF;
END $test$;SELECT '18 dashboard summary cases PASS; no email; fixtures rolled back' AS result;